    { escenaId, duracionSegundos },
    {
      condition: { attr: 'escenaId', exists: true },
      returnValues: 'ALL_NEW'
    }
  );
  return Attributes;
}

import { EntityRepository } from 'dynamodb-toolbox/entity/actions/repository';
import { MODELO_ESCENA, MODELO_ESTUDIO } from '../../models/estudio-escena.model.mjs';

export async function buscarEstudioRepository(estudioId) {
  const { Item } = await MODELO_ESTUDIO.build(EntityRepository).get(
    { estudioId },
    { consistent: true }
  );
  return Item ?? null;
}

export async function consultarEstudioRepository(estudioId, minimo) {
  const { Items = [] } = await MODELO_ESCENA.build(EntityRepository).query(
    { index: 'PorEstudio', partition: estudioId },
    { filters: { Escena: { attr: 'duracionSegundos', gte: minimo } } }
  );
  return Items;
}

import { trasladarEscenaService } from './service.mjs';

export async function handler(event) {
  const escenaId = Number(event.pathParameters.escenaId);
  const { estudioId } = JSON.parse(event.body);
  const resultado = await trasladarEscenaService(escenaId, estudioId);
  return { statusCode: 200, body: JSON.stringify(resultado) };
}

import { trasladarEscenaRepository } from './repository.mjs';
import { buscarEstudioRepository } from '../../estudios/consultar/repository.mjs';

export async function trasladarEscenaService(escenaId, estudioId) {
  const estudio = await buscarEstudioRepository(estudioId);
  if (!estudio) throw new Error('Estudio no encontrado');
  return trasladarEscenaRepository(escenaId, estudioId);
}

